package app

import "github.com/egoist/mygo/ui"

// 图标来自 IconMCP（https://iconmcp.com，MIT 许可）：统一画在 16 格网格上，
// 只有轮廓一种风格，描边用 currentColor，颜色由 TextColor 决定。
func ic16(body string) *ui.SVG {
	return ui.MustParseSVG([]byte(`<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.05" stroke-linecap="round" stroke-linejoin="round">` + body + `</svg>`))
}

// 标题栏按钮的图形按 Windows 的规格画：10×10 的方格、1px 描边。
func captionGlyph(body string) *ui.SVG {
	return ui.MustParseSVG([]byte(`<svg xmlns="http://www.w3.org/2000/svg" width="10" height="10" viewBox="0 0 10 10" fill="none" stroke="currentColor" stroke-width="1" stroke-linecap="square" stroke-linejoin="miter">` + body + `</svg>`))
}

